// ──────────────────────────────────────────────
// Validate and normalize the incoming request
// ──────────────────────────────────────────────
const body = $input.first().json.body || $input.first().json;

const question = (body.question || body.message || '').trim();
const email = (body.email || '').trim().toLowerCase();
const sessionId = body.session_id || body.sessionId || `session_${Date.now()}`;

if (!question) {
  return [{
    json: {
      _error: true,
      response: 'Please provide a question in the request body. Example: { "question": "How do I set up VPN on Firewalla Gold Plus?" }'
    }
  }];
}

// Basic input sanitization (prevent prompt injection attempts)
const sanitized = question
  .replace(/ignore\s+(previous|all|above)\s+instructions?/gi, '[filtered]')
  .replace(/you\s+are\s+now/gi, '[filtered]')
  .replace(/system\s*prompt/gi, '[filtered]')
  .substring(0, 2000); // Limit question length

return [{
  json: {
    question: sanitized,
    email,
    sessionId,
    _error: false
  }
}];

// ──────────────────────────────────────────────
// Format order lookup results for the AI agent
// ──────────────────────────────────────────────
const response = $input.first().json;
const orders = response.orders || [];

if (orders.length === 0) {
  return [{ json: { result: 'No orders found for this email address. The customer may have used a different email to place their order.' } }];
}

const formatted = orders.map(order => {
  const tracking = (order.fulfillments || [])
    .map(f => `${f.tracking_company || 'N/A'}: ${f.tracking_number || 'pending'}`)
    .join(', ') || 'Not yet shipped';

  const items = (order.line_items || [])
    .map(li => `${li.name} x${li.quantity}`)
    .join(', ');

  return [
    `Order ${order.name}:`,
    `  Placed: ${new Date(order.created_at).toLocaleDateString()}`,
    `  Total: $${order.total_price} ${order.currency}`,
    `  Payment: ${order.financial_status}`,
    `  Fulfillment: ${order.fulfillment_status || 'unfulfilled'}`,
    `  Items: ${items}`,
    `  Tracking: ${tracking}`
  ].join('\n');
}).join('\n\n');

return [{ json: { result: formatted } }];

